int main(void) {
    int A, N;
    if (scanf("%d %d", &A, &N) != 2) {
        return 0;
    }

    /*
     * Cada um dos N marinheiros recebe x moedas e o Capitao recebe 2x.
     * Total: A = N*x + 2*x = (N+2)*x  =>  x = A / (N+2)
     * A divisao e perfeita (garantido pelo enunciado),
     * logo o Capitao recebe 2 * (A / (N+2)) moedas.
     */
    int x = A / (N + 2);
    printf("%d\n", 2 * x);

    return 0;
}
